{
  "name": "opencode-shell",
  "version": "0.3.0",
  "description": "OpenCode plugin for running shell commands from the prompt",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/edwardEsmerson/opencode-shell.git"
  },
  "homepage": "https://github.com/edwardEsmerson/opencode-shell#readme",
  "bugs": {
    "url": "https://github.com/edwardEsmerson/opencode-shell/issues"
  },
  "keywords": ["opencode", "plugin", "shell", "terminal"],
  "engines": {
    "opencode": ">=2.0.25 <3"
  },
  "files": ["dist/", "src/", "index.ts", "tui.ts"],
  "scripts": {
    "build": "node scripts/build.mjs && tsc -p tsconfig.build.json",
    "prepare": "npm run build",
    "pretest": "npm run build",
    "test": "tsx --test test/*.test.ts",
    "typecheck": "tsc -p tsconfig.json",
    "prepublishOnly": "npm run typecheck && npm test"
  },
  "exports": {
    ".": { "types": "./dist/index.d.ts", "default": "./dist/index.js" },
    "./server": { "types": "./dist/server.d.ts", "default": "./dist/server.js" },
    "./tui": { "types": "./dist/tui.d.ts", "default": "./dist/tui.js" }
  },
  "dependencies": {
    "@opencode/plugin": "2.0.25"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.16 <0.6",
    "@opentui/solid": ">=0.5.16 <0.6",
    "solid-js": ">=1.9.0 <2"
  },
  "devDependencies": {
    "@babel/core": "7.29.7",
    "@babel/preset-typescript": "7.27.1",
    "@opencode/theme": "2.0.25",
    "@opentui/core": "0.5.16",
    "@opentui/solid": "0.5.16",
    "solid-js": "1.9.12",
    "@types/node": "24.12.2",
    "babel-preset-solid": "1.9.12",
    "tsx": "4.20.5",
    "typescript": "5.8.2"
  },
  "overrides": {
    "seroval": "^1.6.8"
  }
}

import { Plugin } from "@opencode/plugin";
export default Plugin.define({
  id: "opencode-shell",
  // Shell execution belongs to the TUI. The v2 host needs no server hooks.
  setup: async () => {}
});

import { Plugin } from "@opencode/plugin"

export default Plugin.define({
  id: "opencode-shell",
  // Shell execution belongs to the TUI. The v2 host needs no server hooks.
  setup: async () => {},
})
